PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'STUDENT' CHECK(role IN ('ADMIN','FACULTY','STUDENT')),class_code TEXT,roll_no TEXT,phone TEXT,semester TEXT,department TEXT NOT NULL DEFAULT 'Information Technology',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classes (id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,department TEXT NOT NULL DEFAULT 'Information Technology');
CREATE TABLE IF NOT EXISTS notices (id TEXT PRIMARY KEY,title TEXT NOT NULL,content TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'General',priority TEXT NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high')),class_code TEXT,attachment_url TEXT,publish_at TEXT,expires_at TEXT,pinned INTEGER NOT NULL DEFAULT 0,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(class_code) REFERENCES classes(code) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS read_receipts (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,notice_id TEXT NOT NULL,read_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,notice_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(notice_id) REFERENCES notices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS timetable (id INTEGER PRIMARY KEY AUTOINCREMENT,class_code TEXT NOT NULL,day TEXT NOT NULL,period TEXT NOT NULL,subject TEXT NOT NULL,faculty TEXT,room TEXT,FOREIGN KEY(class_code) REFERENCES classes(code) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS faculty (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,department TEXT NOT NULL DEFAULT 'Information Technology',subject TEXT,room TEXT,availability TEXT DEFAULT 'Available',photo TEXT);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT,event_date TEXT NOT NULL,end_date TEXT,location TEXT,organizer TEXT,registration_url TEXT,image_url TEXT,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS assignments (id INTEGER PRIMARY KEY AUTOINCREMENT,class_code TEXT,subject TEXT NOT NULL,title TEXT NOT NULL,description TEXT,due_at TEXT NOT NULL,attachment_url TEXT,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(class_code) REFERENCES classes(code) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS materials (id INTEGER PRIMARY KEY AUTOINCREMENT,class_code TEXT,subject TEXT NOT NULL,title TEXT NOT NULL,description TEXT,file_url TEXT,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(class_code) REFERENCES classes(code) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS exams (id INTEGER PRIMARY KEY AUTOINCREMENT,class_code TEXT,exam_type TEXT NOT NULL DEFAULT 'Internal',subject TEXT NOT NULL,exam_date TEXT NOT NULL,start_time TEXT,end_time TEXT,room TEXT,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(class_code) REFERENCES classes(code) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS attendance (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,subject TEXT NOT NULL,date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Present','Absent')),remarks TEXT,marked_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(marked_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS marks (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,subject TEXT NOT NULL,exam_type TEXT NOT NULL DEFAULT 'Internal',marks REAL NOT NULL,max_marks REAL NOT NULL DEFAULT 100,exam_date TEXT,remarks TEXT,marked_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(marked_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS auth_sessions (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL,revoked_at TEXT,user_agent TEXT,ip_address TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_auth_sessions_user ON auth_sessions(user_id); CREATE INDEX IF NOT EXISTS idx_auth_sessions_expires ON auth_sessions(expires_at); CREATE INDEX IF NOT EXISTS idx_audit_created_user ON audit_logs(user_id,created_at); CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_logs(entity,entity_id,created_at); INSERT OR IGNORE INTO classes(code,name) VALUES ('IT-A','IT-A'),('IT-B','IT-B'),('IT-C','IT-C');